{"files":[{"path":"lib/lore/certify.ts","content":"/**
 * sIVM certification worker: given a column's v_from -> v_to edit, decide
 * which cached v_from cells can be reused as v_to values with expected
 * false-reuse <= alpha (w.p. >= 1-delta), sampling only what the bound needs.
 *
 * The oracle (fresh v_to computation for sampled rows) is injectable so
 * experiments can serve it from a precomputed ground-truth table while
 * production serves it from the live runner. Every oracle call is counted;
 * that count IS the verification cost.
 */
import { randomUUID } from "node:crypto";
import {
  adaptiveCertifyStratum,
  assignStrata,
  diffPrompts,
  planSampleSizes,
  seededShuffle,
  selectReuse,
  type PromptDeltaV1,
  type SivmCellInput,
  type StratumResult,
} from "@lore/core/sivm";
import {
  applyCertificateReuse,
  getCellsForVersion,
  getColumnVersion,
  saveCertificate,
  type AiColumn,
} from "./column-store";
import { bindTemplate } from "./run-column";

type Row = Record<string, unknown>;

/** Returns fresh v_to values for the requested rows. */
export type Oracle = (rowIds: string[]) => Promise<Map<string, unknown>>;

export interface CertifyOptions {
  alpha: number;
  delta: number;
  /** Deterministic seed for the stratified sample (reproducibility). */
  seed?: number;
  /** Persist certificate + apply reuse rows (off for experiments). */
  apply?: boolean;
  /**
   * Grid-adaptive sampling: peek at a doubling look schedule (delta split
   * across looks, so peeking stays valid), stop early on certify or
   * futility. Unlocks small alpha without paying the worst-case sample.
   */
  adaptive?: boolean;
  /** Look-schedule depth for adaptive mode (default 4: 45/90/180/360). */
  maxLooks?: number;
  /**
   * Custom stratifier (e.g. embedding-interaction buckets). Must be frozen
   * before sampling; stratifier quality affects power only, never validity.
   */
  stratifier?: (
    cells: SivmCellInput[],
    delta: PromptDeltaV1,
  ) => ReturnType<typeof assignStrata>;
  /** Guarantee target: user-facing presented cells (default) or the strict
   * unsampled reuse set (deflated threshold). */
  estimand?: "presented" | "reuse-set";
}

export interface CertifyOutcome {
  certificateId: string;
  delta: PromptDeltaV1;
  strata: StratumResult[];
  sampledRowIds: string[];
  reusedRowIds: string[];
  recomputeRowIds: string[];
  oracleCalls: number;
  /** Sampled rows whose fresh value disagreed with cache (by stratum). */
  observedFlips: number;
}

function equivalent(a: unknown, b: unknown): boolean {
  // v1 equivalence: exact for booleans/selects/numbers-as-emitted; the
  // free-text judge path is a Phase 3 upgrade with its own calibrated error.
  return JSON.stringify(a) === JSON.stringify(b);
}

export async function verifyColumnEdit(
  column: AiColumn,
  fromVersion: number,
  toVersion: number,
  rows: Row[],
  idField: string,
  oracle: Oracle,
  opts: CertifyOptions,
): Promise<CertifyOutcome> {
  const vFrom = await getColumnVersion(column.id, fromVersion);
  const vTo = await getColumnVersion(column.id, toVersion);
  if (!vFrom || !vTo) throw new Error("missing column version");

  const delta = diffPrompts(vFrom.prompt_template, vTo.prompt_template);

  const rowById = new Map(rows.map((r) => [String(r[idField]), r]));
  const cached = await getCellsForVersion(column.id, fromVersion, [
    ...rowById.keys(),
  ]);
  const usable = cached.filter(
    (c) => (c.status === "done" || c.status === "cached") && rowById.has(c.row_id),
  );

  // Freeze strata from v_from cache + the prompt delta (pre-sampling).
  const inputs: SivmCellInput[] = usable.map((c) => ({
    rowId: c.row_id,
    cachedValue: c.value,
    boundText: bindTemplate(vFrom.prompt_template, rowById.get(c.row_id)!)
      .text,
  }));
  const strata = (opts.stratifier ?? assignStrata)(inputs, delta);
  const plan = planSampleSizes(
    strata.map((s) => ({ id: s.id, size: s.rowIds.length })),
    opts.alpha,
    opts.delta,
  );

  // Stratified deterministic sample order.
  const seed = opts.seed ?? 42;
  const cacheByRow = new Map(usable.map((c) => [c.row_id, c.value]));
  const fresh = new Map<string, unknown>();
  const revealed = new Set<string>();
  const reveal = async (rowIds: string[]) => {
    const need = rowIds.filter((id) => !revealed.has(id));
    if (need.length > 0) {
      const got = await oracle(need);
      for (const [k, v] of got) fresh.set(k, v);
      for (const id of need) revealed.add(id);
    }
  };

  let results: StratumResult[];
  const sampledByStratum = new Map<string, string[]>();

  if (opts.adaptive) {
    const K = Math.max(1, strata.length);
    const perStratumDelta = opts.delta / K;
    results = [];
    for (const s of strata) {
      const order = seededShuffle(s.rowIds, seed);
      const outcome = await adaptiveCertifyStratum(
        s.rowIds.length,
        opts.alpha,
        perStratumDelta,
        async (n) => {
          const prefix = order.slice(0, n);
          await reveal(prefix);
          return prefix
            .filter((id) => fresh.has(id))
            .map((id) =>
              equivalent(cacheByRow.get(id), fresh.get(id)) ? 0 : 1,
            );
        },
        45,
        opts.maxLooks ?? 4,
        opts.estimand ?? "presented",
      );
      sampledByStratum.set(s.id, order.slice(0, outcome.sampled));
      const last = outcome.looks[outcome.looks.length - 1]!;
      results.push({
        stratumId: s.id,
        size: s.rowIds.length,
        sampled: outcome.sampled,
        flips: last.flips,
        empiricalFlipRate: last.n > 0 ? last.flips / last.n : 1,
        upperBound: last.upperBound,
        certified: outcome.certified,
      });
    }
  } else {
    for (const s of strata) {
      const take = plan.get(s.id) ?? 0;
      sampledByStratum.set(s.id, seededShuffle(s.rowIds, seed).slice(0, take));
    }
    await reveal([...sampledByStratum.values()].flat());
    const mathInput = strata.map((s) => ({
      id: s.id,
      size: s.rowIds.length,
      flipSample: (sampledByStratum.get(s.id) ?? []).flatMap((rowId) => {
        if (!fresh.has(rowId)) return [];
        return [equivalent(cacheByRow.get(rowId), fresh.get(rowId)) ? 0 : 1];
      }),
    }));
    results = selectReuse({
      strata: mathInput,
      alpha: opts.alpha,
      delta: opts.delta,
    });
  }
  const sampledRowIds = [...sampledByStratum.values()].flat();

  const certifiedIds = new Set(
    results.filter((r) => r.certified).map((r) => r.stratumId),
  );
  const sampledSet = new Set(sampledRowIds);
  const reusedRowIds: string[] = [];
  const recomputeRowIds: string[] = [];
  for (const s of strata) {
    for (const rowId of s.rowIds) {
      // Sampled rows are already freshly computed - they are neither reused
      // nor recomputed again.
      if (sampledSet.has(rowId)) continue;
      if (certifiedIds.has(s.id)) reusedRowIds.push(rowId);
      else recomputeRowIds.push(rowId);
    }
  }

  const certificateId = randomUUID();
  if (opts.apply) {
    await saveCertificate({
      id: certificateId,
      columnId: column.id,
      fromVersion,
      toVersion,
      alpha: opts.alpha,
      delta,
      strata: results,
      reusedCount: reusedRowIds.length,
      recomputeCount: recomputeRowIds.length,
      sampledCount: sampledRowIds.length,
      verificationCostUsd: 0,
    });
    await applyCertificateReuse(
      column.id,
      fromVersion,
      toVersion,
      column.model,
      reusedRowIds,
      certificateId,
    );
  }

  return {
    certificateId,
    delta,
    strata: results,
    sampledRowIds,
    reusedRowIds,
    recomputeRowIds,
    oracleCalls: revealed.size,
    observedFlips: results.reduce((a, r) => a + r.flips, 0),
  };
}"}],"concerns":[],"rationale":"Renamed the exported certifyColumnEdit function to verifyColumnEdit in lib/lore/certify.ts while leaving all other files unchanged."}

{"files":[{"path":"lib/lore/run-column.ts","content":"/**
 * The per-cell sub-agent runner: binds a column's prompt template to each
 * row, runs a typed structured-output call, and persists results with
 * caching, a cost ledger, and a pre-run estimate gate.
 *
 * Content hash covers ONLY the row fields the template actually binds — the
 * base of sIVM's cross-version reuse (an edit that adds a bound field changes
 * the hash population; an unrelated row field change does not).
 */
import { createHash } from "node:crypto";
import { generateObject } from "ai";
import { z } from "zod";
import type { ColumnOutputType, RunEstimate } from "@lore/core";
import {
  findCachedByHash,
  recordLedger,
  totalSpendUsd,
  writeCell,
  type AiColumn,
} from "./column-store";
import { CELL_DECODE, EXPERIMENT_BUDGET_USD, MODEL_PRICES } from "./models";

type Row = Record<string, unknown>;

// ---------------------------------------------------------------------------
// Template binding + content hash
// ---------------------------------------------------------------------------

const VAR_RE = /\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g;

export function templateFields(template: string): string[] {
  return [...template.matchAll(VAR_RE)].map((m) => m[1]!);
}

export function bindTemplateCore(
  template: string,
  row: Row,
): { text: string; contentHash: string } {
  const bound: Record<string, unknown> = {};
  const text = template.replaceAll(VAR_RE, (_, field: string) => {
    const v = row[field];
    bound[field] = v ?? null;
    if (v === null || v === undefined) return "(unknown)";
    return Array.isArray(v) ? v.join(", ") : String(v);
  });
  const contentHash = createHash("sha256")
    .update(JSON.stringify(bound))
    .digest("hex");
  return { text, contentHash };
}

// ---------------------------------------------------------------------------
// Output schema per column type (+ exact-shape example for budget models)
// ---------------------------------------------------------------------------

function valueSchema(spec: ColumnOutputType): z.ZodType {
  switch (spec.kind) {
    case "boolean":
      return z.boolean();
    case "number": {
      let n = z.number();
      if (spec.min !== undefined) n = n.min(spec.min);
      if (spec.max !== undefined) n = n.max(spec.max);
      return n;
    }
    case "select":
      return z.enum(spec.options as [string, ...string[]]);
    case "url":
      return z.string();
    case "json":
      return z.record(z.string(), z.unknown());
    case "text":
      return z.string();
  }
}

function exampleFor(spec: ColumnOutputType): string {
  const v =
    spec.kind === "boolean"
      ? "true"
      : spec.kind === "number"
        ? "7"
        : spec.kind === "select"
          ? JSON.stringify(spec.options[0])
          : '"short answer"';
  return `{"value":${v},"rationale":"one short sentence of evidence"}`;
}

function systemFor(spec: ColumnOutputType): string {
  return `You evaluate ONE row of a data table against the user's column
instruction. Judge only from the provided row data; if the data is
insufficient, still commit to the most defensible answer.
Return a JSON object with EXACTLY two keys: "value" and "rationale"
(<= 140 chars). ${
    spec.kind === "select"
      ? `"value" must be exactly one of: ${spec.options.map((o) => JSON.stringify(o)).join(", ")}.`
      : spec.kind === "boolean"
        ? `"value" must be a JSON boolean (true/false), not a string.`
        : spec.kind === "number"
          ? `"value" must be a JSON number${spec.min !== undefined || spec.max !== undefined ? ` between ${spec.min ?? "-inf"} and ${spec.max ?? "inf"}` : ""}.`
          : `"value" must be a string.`
  }
Example shape: ${exampleFor(spec)}`;
}

// ---------------------------------------------------------------------------
// Estimate + run
// ---------------------------------------------------------------------------

const EST_OVERHEAD_TOKENS = 160; // system + schema framing
const EST_OUTPUT_TOKENS = 60;

export function estimateRun(column: AiColumn, rows: Row[]): RunEstimate {
  const price = MODEL_PRICES[column.model] ?? { in: 1, out: 4 };
  let inputTokens = 0;
  for (const row of rows) {
    const { text } = bindTemplateCore(column.prompt_template, row);
    inputTokens += EST_OVERHEAD_TOKENS + Math.ceil(text.length / 4);
  }
  const outputTokens = rows.length * EST_OUTPUT_TOKENS;
  const estCostUsd =
    (inputTokens * price.in + outputTokens * price.out) / 1e6;
  return {
    rowCount: rows.length,
    estInputTokens: inputTokens,
    estOutputTokens: outputTokens,
    estCostUsd,
    requiresConfirmation: rows.length > 100 || estCostUsd > 0.5,
    ...(rows.length > 100 || estCostUsd > 0.5
      ? { reason: "over_absolute_threshold" as const }
      : {}),
  };
}

export interface RunResult {
  ran: number;
  cached: number;
  skipped: number;
  errors: number;
  costUsd: number;
  ms: number;
}

/** Tiny semaphore: bounded concurrency without a dependency. */
async function mapLimit<T, R>(
  items: T[],
  limit: number,
  fn: (item: T) => Promise<R>,
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;
  const workers = Array.from(
    { length: Math.min(limit, items.length) },
    async () => {
      while (next < items.length) {
        const i = next++;
        results[i] = await fn(items[i]!);
      }
    },
  );
  await Promise.all(workers);
  return results;
}

export async function runColumn(
  column: AiColumn,
  rows: Row[],
  idField: string,
  opts?: {
    concurrency?: number;
    /** Run against a specific historical version (sIVM ground truth/verify). */
    versionOverride?: { promptTemplate: string; promptVersion: number };
  },
): Promise<RunResult> {
  const started = Date.now();
  const price = MODEL_PRICES[column.model] ?? { in: 1, out: 4 };
  if (opts?.versionOverride) {
    column = {
      ...column,
      prompt_template: opts.versionOverride.promptTemplate,
      prompt_version: opts.versionOverride.promptVersion,
    };
  }

  // Budget guard: never start a run that would push total spend past the cap.
  const est = estimateRun(column, rows);
  const spent = await totalSpendUsd();
  if (spent + est.estCostUsd > EXPERIMENT_BUDGET_USD) {
    throw new Error(
      `budget guard: $${spent.toFixed(2)} spent + $${est.estCostUsd.toFixed(2)} estimated exceeds the $${EXPERIMENT_BUDGET_USD} cap`,
    );
  }

  let ran = 0;
  let cached = 0;
  let errors = 0;
  let costUsd = 0;
  let inTok = 0;
  let outTok = 0;

  await mapLimit(rows, opts?.concurrency ?? 8, async (row) => {
    const rowId = String(row[idField]);
    const { text, contentHash } = bindTemplateCore(column.prompt_template, row);

    const hit = await findCachedByHash(
      column.id,
      column.prompt_version,
      column.model,
      contentHash,
    );
    if (hit) {
      if (hit.row_id !== rowId) {
        await writeCell({
          columnId: column.id,
          rowId,
          promptVersion: column.prompt_version,
          model: column.model,
          contentHash,
          status: "cached",
          value: hit.value,
          rationale: hit.rationale,
        });
      }
      cached++;
      return;
    }

    const t0 = Date.now();
    try {
      const res = await generateObject({
        model: column.model,
        schema: z.object({
          value: valueSchema(column.output_spec),
          rationale: z.string(),
        }),
        system: systemFor(column.output_spec),
        prompt: text,
        temperature: CELL_DECODE.temperature,
      });
      const cellIn = res.usage.inputTokens ?? 0;
      const cellOut = res.usage.outputTokens ?? 0;
      const cellCost = (cellIn * price.in + cellOut * price.out) / 1e6;
      inTok += cellIn;
      outTok += cellOut;
      costUsd += cellCost;
      await writeCell({
        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "done",
        value: res.object.value,
        rationale: res.object.rationale.slice(0, 500),
        inputTokens: cellIn,
        outputTokens: cellOut,
        costUsd: cellCost,
        latencyMs: Date.now() - t0,
      });
      ran++;
    } catch (err) {
      errors++;
      await writeCell({
        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "error",
        error: err instanceof Error ? err.message.slice(0, 800) : String(err),
        latencyMs: Date.now() - t0,
      });
    }
  });

  await recordLedger({
    kind: "run",
    columnId: column.id,
    model: column.model,
    cells: ran,
    inputTokens: inTok,
    outputTokens: outTok,
    costUsd,
  });

  return {
    ran,
    cached,
    skipped: 0,
    errors,
    costUsd,
    ms: Date.now() - started,
  };
}
"}],"concerns":["lib/lore/certify.ts imports bindTemplate from run-column.ts and will break until its import is updated."],"rationale":"Renamed exported bindTemplate to bindTemplateCore and updated internal call sites."}

{"files":[{"path":"lib/lore/compile-query.ts","content":"/**
 * NL -> FilterSpec compiler: the ONLY probabilistic step in the retrieval
 * plane. One structured-output call maps free text onto the versioned filter
 * schema, grounded in the live field catalog + value vocabulary (schema
 * linking). Execution of the result is fully deterministic and replayable;
 * users edit the result as chips without re-invoking the LLM.
 */
import { generateObject } from "ai";
import { z } from "zod";
import type { FilterPredicate, FilterSpec } from "@lore/core";
import { esAdapter } from "./adapters";
import { buildChips } from "./chips";
import { PROFILE_FIELDS } from "./fields";
import { CELL_DECODE, DEFAULT_MODEL } from "./models";

const KEYWORD_FIELDS = PROFILE_FIELDS.filter((f) => f.type === "keyword").map(
  (f) => f.name,
);
const NUMERIC_FIELDS = PROFILE_FIELDS.filter((f) => f.type === "float").map(
  (f) => f.name,
);

const keywordField = z.enum(KEYWORD_FIELDS as [string, ...string[]]);
const numericField = z.enum(NUMERIC_FIELDS as [string, ...string[]]);

const TermSchema = z.object({
  kind: z.literal("term"),
  field: keywordField,
  value: z.string(),
});
const TermsSchema = z.object({
  kind: z.literal("terms"),
  field: keywordField,
  values: z.array(z.string()).min(1),
});
const RangeSchema = z.object({
  kind: z.literal("range"),
  field: numericField,
  min: z.number().optional(),
  max: z.number().optional(),
});
const ExistsSchema = z.object({
  kind: z.literal("exists"),
  field: z.enum([...KEYWORD_FIELDS, ...NUMERIC_FIELDS] as [string, ...string[]]),
});
const InnerPredicate = z.discriminatedUnion("kind", [
  TermSchema,
  TermsSchema,
  RangeSchema,
  ExistsSchema,
]);
const NotSchema = z.object({
  kind: z.literal("not"),
  predicate: InnerPredicate,
});
const PredicateSchema = z.discriminatedUnion("kind", [
  TermSchema,
  TermsSchema,
  RangeSchema,
  ExistsSchema,
  NotSchema,
]);

const CompileOutput = z.object({
  all: z
    .array(PredicateSchema)
    .describe("Predicates that must ALL hold (AND semantics)"),
  any: z
    .array(PredicateSchema)
    .describe("Optional OR group: at least one must hold; empty if unused"),
  unmapped: z
    .array(z.string())
    .describe(
      "Parts of the query that could not be mapped to any field; empty if none",
    ),
});

export interface CompiledQuery {
  filter: FilterSpec;
  unmapped: string[];
  usage: { inputTokens: number; outputTokens: number };
}

// ---------------------------------------------------------------------------
// Vocabulary: top values per keyword field, computed live and cached.
// ---------------------------------------------------------------------------

let vocabCache: { at: number; text: string } | null = null;
const VOCAB_TTL_MS = 60 * 60 * 1000;

async function vocabulary(): Promise<string> {
  if (vocabCache && Date.now() - vocabCache.at < VOCAB_TTL_MS) {
    return vocabCache.text;
  }
  const agg = await esAdapter().aggregate(
    { schemaVersion: 1, all: [] },
    KEYWORD_FIELDS,
  );
  const lines = PROFILE_FIELDS.map((f) => {
    const base = `- ${f.name} (${f.type}${f.multiValued ? ", multi-valued" : ""}): ${f.description ?? ""}`;
    const buckets = agg[f.name];
    if (!buckets || buckets.length === 0) return base;
    const vals = buckets
      .slice(0, 40)
      .map((b) => JSON.stringify(b.value))
      .join(", ");
    return `${base}\n  values: ${vals}`;
  });
  vocabCache = { at: Date.now(), text: lines.join("\n") };
  return vocabCache.text;
}

// ---------------------------------------------------------------------------
// Compile
// ---------------------------------------------------------------------------

const SYSTEM = `You compile a recruiter-style natural-language query over a table of
89,184 developer profiles (Stack Overflow Survey 2023) into structured filter
predicates. Use ONLY the fields and, for keyword fields, ONLY values from the
vocabulary below (values are exact, case-sensitive strings). Rules:
- "senior"/"experienced" means years_code_pro >= 5 unless a number is given;
  "junior" means years_code_pro <= 2.
- Salary/compensation amounts map to converted_comp_yearly (USD).
- Students: main_branch "I am learning to code" OR employment containing
  "Student, full-time" / "Student, part-time" (use the any group).
- Negations ("not", "without", "excluding") compile to kind:"not".
- Multiple alternatives of the same facet ("Germany or France") compile to one
  kind:"terms" predicate, not an any-group.
- Use the any group ONLY for genuine cross-field OR requirements.
- Anything unmappable to these fields goes into unmapped, verbatim; never
  invent fields or values. Prefer precision over recall.

OUTPUT SHAPE — return a JSON object with EXACTLY these top-level keys:
"all" (array of predicates, AND), "any" (array of predicates, OR group, [] if
unused), "unmapped" (array of strings, [] if none). Predicate shapes, exactly:
  {"kind":"term","field":<field>,"value":<string>}
  {"kind":"terms","field":<field>,"values":[<string>,...]}
  {"kind":"range","field":<numeric field>,"min":<number>,"max":<number>} (min and/or max)
  {"kind":"exists","field":<field>}
  {"kind":"not","predicate":<one of the above>}
No other keys. Ranges use "min"/"max", never gt/gte/lt/lte.

<example>
Query: "remote TypeScript devs in Canada, not managers, 4+ years pro, or anyone at a 10k+ company"
{"all":[{"kind":"term","field":"remote_work","value":"Remote"},{"kind":"term","field":"languages","value":"TypeScript"},{"kind":"term","field":"country","value":"Canada"},{"kind":"not","predicate":{"kind":"term","field":"ic_or_pm","value":"People manager"}},{"kind":"range","field":"years_code_pro","min":4}],"any":[{"kind":"term","field":"org_size","value":"10,000 or more employees"}],"unmapped":[]}
</example>`;

export async function translateQuery(query: string): Promise<CompiledQuery> {
  const vocab = await vocabulary();
  const res = await generateObject({
    model: DEFAULT_MODEL,
    schema: CompileOutput,
    // Pinned like CELL_DECODE: at default sampling temperature this model
    // self-disagrees on 9.5% of draws vs 5.0% at T=0 (measured in the
    // paper), and an unpinned compile occasionally emits degenerate specs
    // (e.g. "NOT 38 languages" instead of "languages = Rust").
    ...CELL_DECODE,
    system: `${SYSTEM}\n\nFIELD CATALOG AND VOCABULARY:\n${vocab}`,
    prompt: `Query: ${JSON.stringify(query)}`,
  });
  const { all, any, unmapped } = res.object;
  const filter: FilterSpec = {
    schemaVersion: 1,
    all: all as FilterPredicate[],
    ...(any.length > 0 ? { any: any as FilterPredicate[] } : {}),
    chips: buildChips(all as FilterPredicate[], any as FilterPredicate[]),
  };
  return {
    filter,
    unmapped,
    usage: {
      inputTokens: res.usage.inputTokens ?? 0,
      outputTokens: res.usage.outputTokens ?? 0,
    },
  };
}

// Chip building lives in ./chips (pure, shared with the client UI).
"}],"concerns":[],"rationale":"Renamed exported function compileQuery to translateQuery with no other changes."}

{"files":[{"path":"lib/lore/certify.ts","content":"/**
 * sIVM certification worker: given a column's v_from -> v_to edit, decide
 * which cached v_from cells can be reused as v_to values with expected
 * false-reuse <= alpha (w.p. >= 1-delta), sampling only what the bound needs.
 *
 * The oracle (fresh v_to computation for sampled rows) is injectable so
 * experiments can serve it from a precomputed ground-truth table while
 * production serves it from the live runner. Every oracle call is counted;
 * that count IS the verification cost.
 */
import { randomUUID } from "node:crypto";
import {
  adaptiveCertifyStratum,
  assignStrata,
  diffPrompts,
  planSampleSizes,
  seededShuffle,
  selectReuse,
  type PromptDeltaV1,
  type SivmCellInput,
  type StratumResult,
} from "@lore/core/sivm";
import {
  applyCertificateReuse,
  getCellsForVersion,
  getColumnVersion,
  saveCertificate,
  type AiColumn,
} from "./column-store";
import { bindTemplate } from "./run-column";

type Row = Record<string, unknown>;

/** Returns fresh v_to values for the requested rows. */
export type Oracle = (rowIds: string[]) => Promise<Map<string, unknown>>;

export interface CertifyOptions {
  alpha: number;
  delta: number;
  /** Deterministic seed for the stratified sample (reproducibility). */
  seed?: number;
  /** Persist certificate + apply reuse rows (off for experiments). */
  apply?: boolean;
  /**
   * Grid-adaptive sampling: peek at a doubling look schedule (delta split
   * across looks, so peeking stays valid), stop early on certify or
   * futility. Unlocks small alpha without paying the worst-case sample.
   */
  adaptive?: boolean;
  /** Look-schedule depth for adaptive mode (default 4: 45/90/180/360). */
  maxLooks?: number;
  /**
   * Custom stratifier (e.g. embedding-interaction buckets). Must be frozen
   * before sampling; stratifier quality affects power only, never validity.
   */
  stratifier?: (
    cells: SivmCellInput[],
    delta: PromptDeltaV1,
  ) => ReturnType<typeof assignStrata>;
  /** Guarantee target: user-facing presented cells (default) or the strict
   * unsampled reuse set (deflated threshold). */
  estimand?: "presented" | "reuse-set";
}

export interface CertifyOutcome {
  certificateId: string;
  delta: PromptDeltaV1;
  strata: StratumResult[];
  sampledRowIds: string[];
  reusedRowIds: string[];
  recomputeRowIds: string[];
  oracleCalls: number;
  /** Sampled rows whose fresh value disagreed with cache (by stratum). */
  observedFlips: number;
}

function equivalent(a: unknown, b: unknown): boolean {
  // v1 equivalence: exact for booleans/selects/numbers-as-emitted; the
  // free-text judge path is a Phase 3 upgrade with its own calibrated error.
  return JSON.stringify(a) === JSON.stringify(b);
}

export async function verifyColumnEdit(
  column: AiColumn,
  fromVersion: number,
  toVersion: number,
  rows: Row[],
  idField: string,
  oracle: Oracle,
  opts: CertifyOptions,
): Promise<CertifyOutcome> {
  const vFrom = await getColumnVersion(column.id, fromVersion);
  const vTo = await getColumnVersion(column.id, toVersion);
  if (!vFrom || !vTo) throw new Error("missing column version");

  const delta = diffPrompts(vFrom.prompt_template, vTo.prompt_template);

  const rowById = new Map(rows.map((r) => [String(r[idField]), r]));
  const cached = await getCellsForVersion(column.id, fromVersion, [
    ...rowById.keys(),
  ]);
  const usable = cached.filter(
    (c) => (c.status === "done" || c.status === "cached") && rowById.has(c.row_id),
  );

  // Freeze strata from v_from cache + the prompt delta (pre-sampling).
  const inputs: SivmCellInput[] = usable.map((c) => ({
    rowId: c.row_id,
    cachedValue: c.value,
    boundText: bindTemplate(vFrom.prompt_template, rowById.get(c.row_id)!)
      .text,
  }));
  const strata = (opts.stratifier ?? assignStrata)(inputs, delta);
  const plan = planSampleSizes(
    strata.map((s) => ({ id: s.id, size: s.rowIds.length })),
    opts.alpha,
    opts.delta,
  );

  // Stratified deterministic sample order.
  const seed = opts.seed ?? 42;
  const cacheByRow = new Map(usable.map((c) => [c.row_id, c.value]));
  const fresh = new Map<string, unknown>();
  const revealed = new Set<string>();
  const reveal = async (rowIds: string[]) => {
    const need = rowIds.filter((id) => !revealed.has(id));
    if (need.length > 0) {
      const got = await oracle(need);
      for (const [k, v] of got) fresh.set(k, v);
      for (const id of need) revealed.add(id);
    }
  };

  let results: StratumResult[];
  const sampledByStratum = new Map<string, string[]>();

  if (opts.adaptive) {
    const K = Math.max(1, strata.length);
    const perStratumDelta = opts.delta / K;
    results = [];
    for (const s of strata) {
      const order = seededShuffle(s.rowIds, seed);
      const outcome = await adaptiveCertifyStratum(
        s.rowIds.length,
        opts.alpha,
        perStratumDelta,
        async (n) => {
          const prefix = order.slice(0, n);
          await reveal(prefix);
          return prefix
            .filter((id) => fresh.has(id))
            .map((id) =>
              equivalent(cacheByRow.get(id), fresh.get(id)) ? 0 : 1,
            );
        },
        45,
        opts.maxLooks ?? 4,
        opts.estimand ?? "presented",
      );
      sampledByStratum.set(s.id, order.slice(0, outcome.sampled));
      const last = outcome.looks[outcome.looks.length - 1]!;
      results.push({
        stratumId: s.id,
        size: s.rowIds.length,
        sampled: outcome.sampled,
        flips: last.flips,
        empiricalFlipRate: last.n > 0 ? last.flips / last.n : 1,
        upperBound: last.upperBound,
        certified: outcome.certified,
      });
    }
  } else {
    for (const s of strata) {
      const take = plan.get(s.id) ?? 0;
      sampledByStratum.set(s.id, seededShuffle(s.rowIds, seed).slice(0, take));
    }
    await reveal([...sampledByStratum.values()].flat());
    const mathInput = strata.map((s) => ({
      id: s.id,
      size: s.rowIds.length,
      flipSample: (sampledByStratum.get(s.id) ?? []).flatMap((rowId) => {
        if (!fresh.has(rowId)) return [];
        return [equivalent(cacheByRow.get(rowId), fresh.get(rowId)) ? 0 : 1];
      }),
    }));
    results = selectReuse({
      strata: mathInput,
      alpha: opts.alpha,
      delta: opts.delta,
    });
  }
  const sampledRowIds = [...sampledByStratum.values()].flat();

  const certifiedIds = new Set(
    results.filter((r) => r.certified).map((r) => r.stratumId),
  );
  const sampledSet = new Set(sampledRowIds);
  const reusedRowIds: string[] = [];
  const recomputeRowIds: string[] = [];
  for (const s of strata) {
    for (const rowId of s.rowIds) {
      // Sampled rows are already freshly computed - they are neither reused
      // nor recomputed again.
      if (sampledSet.has(rowId)) continue;
      if (certifiedIds.has(s.id)) reusedRowIds.push(rowId);
      else recomputeRowIds.push(rowId);
    }
  }

  const certificateId = randomUUID();
  if (opts.apply) {
    await saveCertificate({
      id: certificateId,
      columnId: column.id,
      fromVersion,
      toVersion,
      alpha: opts.alpha,
      delta,
      strata: results,
      reusedCount: reusedRowIds.length,
      recomputeCount: recomputeRowIds.length,
      sampledCount: sampledRowIds.length,
      verificationCostUsd: 0,
    });
    await applyCertificateReuse(
      column.id,
      fromVersion,
      toVersion,
      column.model,
      reusedRowIds,
      certificateId,
    );
  }

  return {
    certificateId,
    delta,
    strata: results,
    sampledRowIds,
    reusedRowIds,
    recomputeRowIds,
    oracleCalls: revealed.size,
    observedFlips: results.reduce((a, r) => a + r.flips, 0),
  };
}
"}],"concerns":["The route at app/api/lore/columns/[id]/certify/route.ts still imports certifyColumnEdit and will fail until updated, but it was left untouched per instructions."],"rationale":"Renamed the exported function from certifyColumnEdit to verifyColumnEdit as requested."}

{"files":[{"path":"lib/lore/chips.ts","content":"import type { FilterChip, FilterPredicate } from "@lore/core";
import { PROFILE_FIELDS } from "./fields";

/** Pure chip/label helpers shared by server compiler and client UI. */

export const FIELD_LABELS: Record<string, string> = Object.fromEntries(
  PROFILE_FIELDS.map((f) => [
    f.name,
    f.name
      .split("_")
      .map((w) => w[0]!.toUpperCase() + w.slice(1))
      .join(" "),
  ]),
);

export function predicateLabel(p: FilterPredicate): string {
  switch (p.kind) {
    case "term":
      return `${FIELD_LABELS[p.field]}: ${p.value}`;
    case "terms":
      return `${FIELD_LABELS[p.field]}: ${p.values.slice(0, 2).join(", ")}${
        p.values.length > 2 ? ` +${p.values.length - 2}` : ""
      }`;
    case "range": {
      const parts: string[] = [];
      if (p.min !== undefined) parts.push(`≥ ${p.min}`);
      if (p.max !== undefined) parts.push(`≤ ${p.max}`);
      return `${FIELD_LABELS[p.field]} ${parts.join(" and ")}`;
    }
    case "exists":
      return `Has ${FIELD_LABELS[p.field]}`;
    case "not":
      return `NOT ${predicateLabel(p.predicate)}`;
    case "geo":
      return `${FIELD_LABELS[p.field]} within ${p.radiusMiles}mi`;
    case "text":
      return `"${p.query}"`;
  }
}

export function assembleChips(
  all: FilterPredicate[],
  any: FilterPredicate[],
): FilterChip[] {
  const chips: FilterChip[] = all.map((p, i) => ({
    id: `all-${i}`,
    label: predicateLabel(p),
    predicates: [i],
    source: "extracted" as const,
    ...(p.kind === "terms" && p.values.length > 2
      ? { expansions: p.values.map(String) }
      : {}),
  }));
  if (any.length > 0) {
    chips.push({
      id: "any-group",
      label: `Any of: ${any.map(predicateLabel).join(" · ")}`,
      predicates: any.map((_, i) => i),
      source: "extracted",
    });
  }
  return chips;
}
"}],"concerns":["Renaming only the definition in lib/lore/chips.ts leaves call sites in lib/lore/compile-query.ts referencing buildChips, so the repository will not build cleanly until those are updated."],"rationale":"Renamed exported function buildChips to assembleChips in lib/lore/chips.ts per assignment."}

{"files":[{"path":"lib/chat/local-store.ts","content":""use client";

import type { HandleMessageStreamEvent, SessionState } from "eve/client";
import { createFallbackTitle, DEFAULT_CHAT_TITLE } from "@/lib/chat/title";
import type { ActiveChat, ChatListItem } from "@/lib/chat/types";

const STORAGE_KEY = "eve-chat-template:chats";
const STORAGE_VERSION = 1;
const MAX_STORED_CHATS = 50;

type StoredChat = ActiveChat & {
  readonly updatedAt: string;
};

type StoredChatState = {
  readonly chats: readonly StoredChat[];
  readonly version: typeof STORAGE_VERSION;
};

export function listLocalChats(): ChatListItem[] {
  return readState().chats.map(toListItem);
}

export function getLocalChat(chatId: string): ActiveChat | null {
  const chat = readState().chats.find((item) => item.id === chatId);

  return chat ? toActiveChat(chat) : null;
}

export function createLocalChat(pendingUserMessage?: string) {
  const pendingMessage = pendingUserMessage?.trim() || null;
  const now = new Date().toISOString();
  const chat: StoredChat = {
    events: [],
    id: crypto.randomUUID(),
    pendingUserMessage: pendingMessage,
    session: undefined,
    title: pendingMessage ? createFallbackTitle(pendingMessage) : DEFAULT_CHAT_TITLE,
    updatedAt: now,
  };

  updateState((chats) => [chat, ...chats]);

  return toListItem(chat);
}

export function deleteLocalChat(chatId: string) {
  updateState((chats) => chats.filter((chat) => chat.id !== chatId));
}

export function markLocalChatPendingMessage(chatId: string, message: string) {
  const pendingMessage = message.trim();

  if (!pendingMessage) {
    throw new Error("Message cannot be empty.");
  }

  return updateChat(chatId, (chat) => ({
    ...chat,
    pendingUserMessage: pendingMessage,
    title:
      chat.title === DEFAULT_CHAT_TITLE
        ? createFallbackTitle(pendingMessage)
        : chat.title,
    updatedAt: new Date().toISOString(),
  }));
}

export function clearLocalChatPendingMessage(chatId: string) {
  updateChat(chatId, (chat) => ({
    ...chat,
    pendingUserMessage: null,
  }));
}

export function pushLocalChatEvent({
  chatId,
  event,
  eventIndex,
}: {
  readonly chatId: string;
  readonly event: HandleMessageStreamEvent;
  readonly eventIndex: number;
}) {
  updateChat(chatId, (chat) => {
    const events = [...chat.events];

    if (eventIndex >= events.length) {
      events.push(event);
    } else {
      events[eventIndex] = event;
    }

    return { ...chat, events };
  });
}

export function saveLocalChatSession(chatId: string, session: SessionState) {
  updateChat(chatId, (chat) => ({ ...chat, session }));
}

export function saveLocalChatSnapshot({
  chatId,
  events,
  session,
}: {
  readonly chatId: string;
  readonly events: readonly HandleMessageStreamEvent[];
  readonly session: SessionState;
}) {
  updateChat(chatId, (chat) => ({
    ...chat,
    events,
    pendingUserMessage: null,
    session,
    updatedAt: new Date().toISOString(),
  }));
}

export function skipLocalChatAuthorization({
  chatId,
  events,
  session,
}: {
  readonly chatId: string;
  readonly events: readonly HandleMessageStreamEvent[];
  readonly session: SessionState;
}) {
  const chat = updateChat(chatId, (current) => ({
    ...current,
    events: [...current.events, ...events],
    pendingUserMessage: null,
    session,
    updatedAt: new Date().toISOString(),
  }));

  return {
    chat: toListItem(chat),
    eventCount: events.length,
    eventIndex: chat.events.length - events.length,
  };
}

function updateChat(chatId: string, update: (chat: StoredChat) => StoredChat) {
  const currentChat = readState().chats.find((chat) => chat.id === chatId);

  if (!currentChat) {
    throw new Error("Chat not found.");
  }

  const updatedChat = update(currentChat);

  updateState((chats) =>
    chats.map((chat) => (chat.id === chatId ? updatedChat : chat)),
  );

  return updatedChat;
}

function updateState(update: (chats: readonly StoredChat[]) => readonly StoredChat[]) {
  const nextChats = [...update(readState().chats)]
    .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
    .slice(0, MAX_STORED_CHATS);

  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ chats: nextChats, version: STORAGE_VERSION } satisfies StoredChatState),
    );
  } catch {
    throw new Error("Browser storage is full. Delete an older chat and try again.");
  }
}

function readState(): StoredChatState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);

    if (!raw) {
      return emptyState();
    }

    const parsed = JSON.parse(raw) as Partial<StoredChatState>;

    if (parsed.version !== STORAGE_VERSION || !Array.isArray(parsed.chats)) {
      return emptyState();
    }

    const chats = parsed.chats.filter(isStoredChat);

    return { chats, version: STORAGE_VERSION };
  } catch {
    return emptyState();
  }
}

function isStoredChat(value: unknown): value is StoredChat {
  if (!value || typeof value !== "object") {
    return false;
  }

  const chat = value as Partial<StoredChat>;

  return (
    typeof chat.id === "string" &&
    typeof chat.title === "string" &&
    typeof chat.updatedAt === "string" &&
    Array.isArray(chat.events)
  );
}

function toActiveChat(chat: StoredChat): ActiveChat {
  return {
    events: chat.events,
    id: chat.id,
    pendingUserMessage: chat.pendingUserMessage ?? null,
    session: chat.session,
    title: chat.title,
  };
}

function toListItem(chat: StoredChat): ChatListItem {
  return {
    id: chat.id,
    title: chat.title,
    updatedAt: chat.updatedAt,
  };
}

function emptyState(): StoredChatState {
  return { chats: [], version: STORAGE_VERSION };
}
"},{"path":"lib/chat/persistence-client.ts","content":""use client";

import type { HandleMessageStreamEvent, SessionState } from "eve/client";
import {
  appendChatEventAction,
  checkSendLimitAction,
  clearChatPendingMessageAction,
  createChatAction,
  deleteChatAction,
  markChatPendingMessageAction,
  saveChatSessionStateAction,
  saveChatSnapshotAction,
  skipChatAuthorizationAction,
} from "@/app/actions/chat";
import {
  clearLocalChatPendingMessage,
  createLocalChat,
  deleteLocalChat,
  getLocalChat,
  listLocalChats,
  markLocalChatPendingMessage,
  pushLocalChatEvent,
  saveLocalChatSession,
  saveLocalChatSnapshot,
  skipLocalChatAuthorization,
} from "@/lib/chat/local-store";
import type { StorageMode } from "@/lib/chat/types";

export function listClientChats(storageMode: StorageMode) {
  return storageMode === "browser" ? listLocalChats() : [];
}

export async function getClientChat(storageMode: StorageMode, chatId: string) {
  if (storageMode === "browser") {
    return getLocalChat(chatId);
  }

  const response = await fetch(`/api/chats/${encodeURIComponent(chatId)}`);

  if (!response.ok) {
    throw new Error(response.status === 404 ? "Chat not found." : "Failed to load chat history.");
  }

  const data = (await response.json()) as {
    readonly chat: ReturnType<typeof getLocalChat>;
  };

  return data.chat;
}

export async function createClientChat(
  storageMode: StorageMode,
  input?: { readonly pendingUserMessage?: string },
) {
  return storageMode === "browser"
    ? createLocalChat(input?.pendingUserMessage)
    : createChatAction(input);
}

export async function deleteClientChat(storageMode: StorageMode, chatId: string) {
  if (storageMode === "browser") {
    deleteLocalChat(chatId);
    return;
  }

  await deleteChatAction(chatId);
}

export async function checkClientSendLimit(
  storageMode: StorageMode,
  input?: { readonly message?: string },
) {
  return storageMode === "browser"
    ? ({ allowed: true } as const)
    : checkSendLimitAction(input);
}

export async function markClientChatPendingMessage(
  storageMode: StorageMode,
  input: { readonly chatId: string; readonly message: string },
) {
  return storageMode === "browser"
    ? markLocalChatPendingMessage(input.chatId, input.message)
    : markChatPendingMessageAction(input);
}

export async function clearClientChatPendingMessage(
  storageMode: StorageMode,
  chatId: string,
) {
  if (storageMode === "browser") {
    clearLocalChatPendingMessage(chatId);
    return;
  }

  await clearChatPendingMessageAction(chatId);
}

export async function appendClientChatEvent(
  storageMode: StorageMode,
  input: {
    readonly chatId: string;
    readonly event: HandleMessageStreamEvent;
    readonly eventIndex: number;
  },
) {
  if (storageMode === "browser") {
    pushLocalChatEvent(input);
    return;
  }

  await appendChatEventAction(input);
}

export async function saveClientChatSession(
  storageMode: StorageMode,
  input: { readonly chatId: string; readonly session: SessionState },
) {
  if (storageMode === "browser") {
    saveLocalChatSession(input.chatId, input.session);
    return;
  }

  await saveChatSessionStateAction(input);
}

export async function saveClientChatSnapshot(
  storageMode: StorageMode,
  input: {
    readonly chatId: string;
    readonly events: readonly HandleMessageStreamEvent[];
    readonly session: SessionState;
  },
) {
  if (storageMode === "browser") {
    saveLocalChatSnapshot(input);
    return;
  }

  await saveChatSnapshotAction(input);
}

export async function skipClientChatAuthorization(
  storageMode: StorageMode,
  input: {
    readonly chatId: string;
    readonly events: readonly HandleMessageStreamEvent[];
    readonly session: SessionState;
  },
) {
  return storageMode === "browser"
    ? skipLocalChatAuthorization(input)
    : skipChatAuthorizationAction(input);
}
